// Vehicle Lane instantiations where VehicleLane( int size, int speed, int[-1, GRID_W]& init_x[MAX_VEHICLES], int n, int[0, GRID_H-1] init_y )
// Lane OC - OrangeCar (posizioni: 4, 14)
OC = VehicleLane(3, oc_x, 1);

// Lane B - Bulldozer (posizioni: 2, 11)
B = VehicleLane(10, b_x, 2);

// Lane GC - GreenCar (posizioni: 4, 8, 12, 16)
GC = VehicleLane(5, gc_x, 3);

// Lane PC - PurpleCar (posizioni: 2, 10)
PC = VehicleLane(4, pc_x, 4);

// Lane T - Truck (size 2, posizioni: 4, 15)
T = VehicleLane(7, t_x, 5);

// Floating Objects
F1 = FloatingLane(6, f1_x, 7);
F2 = FloatingLane(2, f2_x, 8);
F3 = FloatingLane(7, f3_x, 9);
F4 = FloatingLane(2, f4_x, 10);
F5 = FloatingLane(2, f5_x, 11);

// Frog
F = Frog();

system OC, B, GC, PC, T, F, F1, F2, F3, F4, F5;
